#include <Adafruit_NeoPixel.h>

// ---------- ПИНЫ ----------
#define BUTTON_LEFT   5
#define BUTTON_RIGHT  6
#define LIGHT_LEFT    A4
#define LIGHT_RIGHT   A0
#define ADDRESS_LED   A1
#define NUM_LEDS      4
#define REED_LEFT     4
#define REED_RIGHT    3
#define BUZZER_PIN    8      // вход PAM8403 (через делитель/RC, см. ниже)

Adafruit_NeoPixel strip(NUM_LEDS, ADDRESS_LED, NEO_GRB + NEO_KHZ800);

// ---------- СОСТОЯНИЕ ----------
bool hazard        = false;
bool redMode       = false;
bool ignoreLeftTurn  = false;
bool ignoreRightTurn = false;

bool blinkState    = false;
bool turnJustActivated = false;

unsigned long lastBlink       = 0;
unsigned long lastLeftClick   = 0;
unsigned long lastRightClick  = 0;

bool lastLeftState  = HIGH;
bool lastRightState = HIGH;
bool lastReedLeft   = HIGH;
bool lastReedRight  = HIGH;

// ---------- КОНСТАНТЫ ----------
const unsigned long DOUBLE_CLICK_TIME = 700;
const unsigned long BLINK_INTERVAL    = 300;

// Пикание поворотников: 2 импульса на цикл мигания
// (как у настоящих реле поворотов)
bool          beepPhase      = false;   // false = пауза, true = пикаем
unsigned long lastBeepChange = 0;
const unsigned long BEEP_ON_MS  = 60;   // длительность "пик"
const unsigned long BEEP_GAP_MS = 90;   // пауза между двумя "пиками"
// Цикл: ON 60 → OFF 90 → ON 60 → OFF (до конца blink-полупериода)
byte beepStep = 0;   // 0..3

// ---------- ПРОТОТИПЫ ----------
void handleLeftButton(bool left);
void handleRightButton(bool right);
void updateBlink();
void updateReedLeds();
void updateTurnLights(bool left, bool right, bool reedLeft, bool reedRight);
void updateBuzzer(bool turnActive);
void setBuzzer(bool on);

// ================================================================
void setup() {
  pinMode(BUTTON_LEFT,  INPUT_PULLUP);
  pinMode(BUTTON_RIGHT, INPUT_PULLUP);
  pinMode(REED_LEFT,    INPUT_PULLUP);
  pinMode(REED_RIGHT,   INPUT_PULLUP);
  pinMode(LIGHT_LEFT,   OUTPUT);
  pinMode(LIGHT_RIGHT,  OUTPUT);
  pinMode(BUZZER_PIN,   OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  strip.begin();
  strip.setBrightness(255);

  // Стартовый тест
  for (int i = 0; i < NUM_LEDS; i++)
    strip.setPixelColor(i, strip.Color(30, 0, 0));
  strip.show();
  delay(250);

  for (byte i = 0; i < 3; i++) {
    digitalWrite(LIGHT_LEFT,  HIGH);
    digitalWrite(LIGHT_RIGHT, HIGH);
    // PAM8403: пикаем прямоугольником 4 кГц, 80 мс
    setBuzzer(true); delay(80); setBuzzer(false);
    delay(320);
    digitalWrite(LIGHT_LEFT,  LOW);
    digitalWrite(LIGHT_RIGHT, LOW);
    delay(400);
  }

  delay(800);
  strip.clear();
  strip.show();
}

// ================================================================
void loop() {
  bool left  = digitalRead(BUTTON_LEFT);
  bool right = digitalRead(BUTTON_RIGHT);

  bool reedLeft  = digitalRead(REED_LEFT);
  bool reedRight = digitalRead(REED_RIGHT);

  handleLeftButton(left);
  handleRightButton(right);

  lastLeftState  = left;
  lastRightState = right;

  if (left  == HIGH) ignoreLeftTurn  = false;
  if (right == HIGH) ignoreRightTurn = false;

  // Мгновенное срабатывание герконов (без ожидания blink)
  updateReedLeds();

  updateBlink();
  updateTurnLights(left, right, reedLeft, reedRight);

  // Зуммер только если реально есть активный поворот
  bool turnActive = hazard
                 || (left  == LOW && !ignoreLeftTurn)
                 || (right == LOW && !ignoreRightTurn);
  updateBuzzer(turnActive);
}

// ================================================================
void handleLeftButton(bool left) {
  if (lastLeftState == HIGH && left == LOW) {
    if (hazard) {
      hazard = false;
      ignoreLeftTurn = false;
      lastLeftClick  = millis();
      turnJustActivated = true;
    } else if (millis() - lastLeftClick < DOUBLE_CLICK_TIME) {
      redMode = !redMode;
      ignoreLeftTurn = true;
      lastLeftClick  = 0;
    } else {
      lastLeftClick = millis();
      turnJustActivated = true;
    }
  }
}

void handleRightButton(bool right) {
  if (lastRightState == HIGH && right == LOW) {
    if (hazard) {
      hazard = false;
      ignoreRightTurn = false;
      lastRightClick  = millis();
      turnJustActivated = true;
    } else if (millis() - lastRightClick < DOUBLE_CLICK_TIME) {
      hazard = true;
      ignoreRightTurn = true;
      lastRightClick  = 0;
      turnJustActivated = true;
    } else {
      lastRightClick = millis();
      turnJustActivated = true;
    }
  }
}

// ================================================================
void updateBlink() {
  bool turnActive = hazard
                 || (digitalRead(BUTTON_LEFT)  == LOW && !ignoreLeftTurn)
                 || (digitalRead(BUTTON_RIGHT) == LOW && !ignoreRightTurn);

  if (turnJustActivated && turnActive) {
    blinkState = true;
    lastBlink  = millis();
    beepStep   = 0;
    lastBeepChange = millis();
    turnJustActivated = false;
  }

  if (turnActive) {
    if (millis() - lastBlink >= BLINK_INTERVAL) {
      lastBlink = millis();
      blinkState = !blinkState;
      // при смене полупериода сбрасываем паттерн пикания
      beepStep = 0;
      lastBeepChange = millis();
    }
  } else {
    turnJustActivated = false;
    blinkState = false;
  }
}

// ================================================================
void updateReedLeds() {
  // Герконы читаются каждый loop — LED обновляется моментально
  bool reedLeft  = digitalRead(REED_LEFT);
  bool reedRight = digitalRead(REED_RIGHT);

  uint8_t r, g, b;
  if (redMode) { r = 20; g = 0; b = 0; }
  else         { r = 0;  g = 0; b = 0; }

  for (int i = 0; i < NUM_LEDS; i++) {
    bool isLeftLed = (i < 2);
    bool reedActive = isLeftLed ? (reedLeft == LOW) : (reedRight == LOW);

    if (reedActive) {
      strip.setPixelColor(i, strip.Color(255, 0, 0));  // СТОП
    } else {
      strip.setPixelColor(i, strip.Color(r, g, b));    // габарит/выкл
    }
  }
  strip.show();
}

// ================================================================
void updateTurnLights(bool left, bool right, bool reedLeft, bool reedRight) {
  if (hazard) {
    digitalWrite(LIGHT_LEFT,  blinkState);
    digitalWrite(LIGHT_RIGHT, blinkState);
  } else if (left == LOW && !ignoreLeftTurn) {
    digitalWrite(LIGHT_LEFT,  blinkState);
    digitalWrite(LIGHT_RIGHT, LOW);
  } else if (right == LOW && !ignoreRightTurn) {
    digitalWrite(LIGHT_RIGHT, blinkState);
    digitalWrite(LIGHT_LEFT,  LOW);
  } else {
    digitalWrite(LIGHT_LEFT,  LOW);
    digitalWrite(LIGHT_RIGHT, LOW);
  }
}

// ================================================================
// PAM8403 — усилитель, ему нужен прямоугольник звуковой частоты
// на входе. Пикаем ~2.7 кГц пачками, как реле поворотов.
void updateBuzzer(bool turnActive) {
  if (!turnActive) {
    setBuzzer(false);
    beepStep = 0;
    return;
  }

  unsigned long now = millis();
  unsigned long dt  = now - lastBeepChange;

  switch (beepStep) {
    case 0:  // ПИК #1
      setBuzzer(true);
      if (dt >= BEEP_ON_MS)  { beepStep = 1; lastBeepChange = now; }
      break;
    case 1:  // пауза
      setBuzzer(false);
      if (dt >= BEEP_GAP_MS) { beepStep = 2; lastBeepChange = now; }
      break;
    case 2:  // ПИК #2
      setBuzzer(true);
      if (dt >= BEEP_ON_MS)  { beepStep = 3; lastBeepChange = now; }
      break;
    case 3:  // пауза до конца цикла (ждём смены blinkState)
      setBuzzer(false);
      // остаёмся в этом шаге, пока updateBlink не сбросит beepStep в 0
      break;
  }
}

// ================================================================
// Генерация прямоугольника для PAM8403 через software PWM
inline void setBuzzer(bool on) {
  if (on) {
    // ~2.7 кГц: 370 мкс период, 185 мкс полупериод
    // Простая генерация пачкой, чтобы усилитель "увидел" сигнал
    for (byte i = 0; i < 20; i++) {
      digitalWrite(BUZZER_PIN, HIGH);
      delayMicroseconds(185);
      digitalWrite(BUZZER_PIN, LOW);
      delayMicroseconds(185);
    }
  } else {
    digitalWrite(BUZZER_PIN, LOW);
  }
}
